// zhi168 native video API. baseUrl stays /api/openai for model discovery.
const root = new URL(baseUrl).origin;
const headers = { "X-API-Key": apiKey };
const call = async (options) => {
  try {
    return await request({ ...options, headers: { ...headers, ...options.headers } });
  } catch (error) {
    const detail = error?.response?.data?.detail;
    throw new Error(typeof detail === "string" ? detail : error.message);
  }
};
const catalog = await call({ method: "get", url: `${root}/api/v1/models` });
const selected = catalog.find((entry) => entry.model_code === model && entry.capability === "video");
if (!selected) throw new Error(`当前 API 无可用视频模型：${model}`);
const supported = selected.supported_params || {};
const duration = Number(params.seconds || selected.default_params.duration_seconds);
const resolution = String(params.resolution || selected.default_params.resolution);
const ratio = params.ratio && params.ratio !== "auto" ? params.ratio : selected.default_params.aspect_ratio || "16:9";
if (supported.resolution?.length && !supported.resolution.includes(resolution)) {
  throw new Error(`${model} 支持的分辨率：${supported.resolution.join("、")}，请调整视频设置`);
}
if (supported.aspect_ratio?.length && !supported.aspect_ratio.includes(ratio)) {
  throw new Error(`${model} 支持的比例：${supported.aspect_ratio.join("、")}`);
}
const durations = supported.duration_seconds || {};
if ((durations.options?.length && !durations.options.includes(duration)) || (durations.min !== undefined && duration < durations.min) || (durations.max !== undefined && duration > durations.max)) {
  throw new Error(`${model} 的时长不支持 ${duration} 秒，请按模型支持范围调整`);
}
const fields = { model_code: model, prompt, duration_seconds: duration, resolution, aspect_ratio: ratio, with_audio: params.generateAudio !== false };
let created;
if (images.length || videos.length || audios.length) {
  const form = new FormData();
  for (const [name, value] of Object.entries(fields)) form.set(name, String(value));
  for (const image of images) {
    if (/^https?:\/\//i.test(image)) form.append("reference_image_urls", image);
    else form.append("reference_images", await (await fetch(image)).blob(), "reference.png");
  }
  for (const video of videos) form.append("video_files", video);
  for (const audio of audios) form.append("audio_files", audio);
  created = await call({ method: "post", url: `${root}/api/v1/video-tasks/multipart`, data: form });
} else {
  created = await call({ method: "post", url: `${root}/api/v1/video-tasks`, headers: { "Content-Type": "application/json" }, data: fields });
}
if (!created.task_id) throw new Error("视频接口未返回任务 ID");
return await poll(
  () => call({ method: "get", url: `${root}/api/v1/video-tasks/${encodeURIComponent(created.task_id)}` }),
  (task) => {
    if (["failed", "cancelled", "canceled"].includes(task.status)) throw new Error(task.error_message || "视频生成失败");
    if (task.status !== "succeeded") return null;
    if (!task.result_url) throw new Error("任务成功但未返回视频地址");
    return { url: task.result_url };
  },
);

